    "description": "Sejam bem vindos (as) à ANFRA IMÓVEIS ! É com prazer que apresentamos esta casa no bairro Nossa Senhora de Lourdes, em Ibirité. Localizada em um dos melhores pontos do bairro, estando à poucos metros de ampla variedade de comércios e servios, além de fácil acesso ao Centro de Ibirité e Região do Barreiro. Lote com 210m² e mais de 200m² construídos. Projeto aconchegante, contando com duas casas (disponibilidade para unificação das mesmas). A casa principal conta com aproximadamente 130m², distribuídos em: 3 quartos, sala para dois ambientes, cozinha amplam, banho social, área de serviço e varanda. A segunda casa conta com aproximadamente 80m², distribuídos em: 2 quartos, cozinha estilo americana, sala de estar, sala de jantar, banho social, área de serviço e varanda parcialmente coberta. Ambas as casas contam com acabamento cerâmico e armários na cozinha. Cômodos amplos, bem arejados e iluminados, garantindo maior conforto e comodidade à família. Garagem para dois carros, sendo uma delas coberta. Imóvel possui escritura e registro. Não financiável. Agende já sua visita! Fique por dentro das novidades, siga-nos nas redes sociais: @anfraimoveis O imóvel que você procura a ANFRA tem! As informações estão sujeitas a alterações. Consulte o corretor responsável.",
